# DDL: (key, difficulty, spec, start_schema, seed_sql, probes, reference)
def P(label, sql, expect="ok", setup=(), rows=None, err="integrity", ordered=False):
    d = {"label": label, "sql": sql, "expect": expect, "setup": list(setup), "err": err, "ordered": ordered}
    if rows is not None:
        d["rows"] = rows
    return d


